PACKAGE_SUBPACKAGES: dict[str, tuple[str, ...]] = {'qfluentwidgets': ('_rc', 'common', 'components', 'multimedia', 'window'),
 'qfluentwidgets.components': ('date_time',
                               'dialog_box',
                               'layout',
                               'material',
                               'navigation',
                               'settings',
                               'widgets')}


def loadExport(packageName: str, packageGlobals: dict[str, object], name: str) -> object:
    exports = PACKAGE_EXPORTS.get(packageName)
    if exports is not None and name in exports:
        module = importlib.import_module(exports[name])
        value = getattr(module, name)
        packageGlobals[name] = value
        return value
    subpackages = PACKAGE_SUBPACKAGES.get(packageName, ())
    if name in subpackages:
        value = importlib.import_module(f'{packageName}.{name}')
        packageGlobals[name] = value
        return value
    raise AttributeError(f'module {packageName!r} has no attribute {name!r}')


def listExports(packageName: str) -> list[str]:
    return sorted(PACKAGE_EXPORTS.get(packageName, ()))


def listDir(packageName: str) -> list[str]:
    exports = PACKAGE_EXPORTS.get(packageName, {})
    subpackages = PACKAGE_SUBPACKAGES.get(packageName, ())
    return sorted(set(exports) | set(subpackages))
